@namespace sv_c181217b462d49e9a789395914fe80d3.Components.Pages.Board

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@Title</strong>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body overflow-auto" style="max-height: 60vh;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          OnMoveLeft="() => OnMoveTaskLeft.InvokeAsync(task.Id)"
                          OnMoveRight="() => OnMoveTaskRight.InvokeAsync(task.Id)" />
            }

            @if (showForm)
            {
                <AddTaskForm OnTaskCreated="HandleTaskCreated" OnCancel="() => showForm = false" />
            }
            else
            {
                <button class="btn btn-sm btn-outline-primary w-100 mt-2" @onclick="() => showForm = true">Add Task</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveTaskLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveTaskRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleTaskCreated(TaskItem task)
    {
        await OnAddTask.InvokeAsync(task);
        showForm = false;
    }
}

